        if (!killCamLight.parent) cinematicCamera.add(killCamLight);
        if (!killCamAmbient) killCamAmbient = new THREE.AmbientLight(0xffffff, 0.22);
        if (!killCamAmbient.parent) scene.add(killCamAmbient);
