    ai.ammoRR = selected === WEAPON_RR ? MAX_AMMO_RR : 0;
    ai.ammoSR = selected === WEAPON_SR ? MAX_AMMO_SR : 0;
    ai.ammoSG = selected === WEAPON_SG ? MAX_AMMO_SG : 0;
